"""Channel-neutral turn metric instruments: declarative specs and registration.

Each instrument is fully described by one
:class:`~rasa.tracing.shared.instrument_spec.InstrumentSpec` in
``TURN_INSTRUMENT_SPECS`` — name, kind, unit, description, attribute
allowlist, and histogram buckets. The SDK Views and the registered
instruments are both derived from that single source of truth, so the
allowlist enforced at export time can never drift from the declaration.

Instruments exist only after :func:`register_turn_metric_instruments` runs
(invoked from ``rasa.tracing.metrics_config.configure_metrics``); until then
lookups return ``None`` and the recording functions stay no-ops.
"""

from __future__ import annotations

from typing import List, Tuple

from opentelemetry.sdk.metrics.view import View

from rasa.tracing.shared.instrument_registry import register_instruments
from rasa.tracing.shared.instrument_spec import InstrumentKind, InstrumentSpec
from rasa.tracing.turn import semconv

# ---------------------------------------------------------------------------
# Histogram buckets (seconds)
# ---------------------------------------------------------------------------

# Turn duration ranges from sub-second commands to LLM-backed turns and
# provider timeouts.
TURN_DURATION_BUCKET_BOUNDARIES_S = (
    0.1,
    0.25,
    0.5,
    1.0,
    2.5,
    5.0,
    10.0,
    20.0,
    30.0,
    60.0,
    120.0,
)

# Use denser buckets below three seconds, where latency differences matter most.
TURN_TIME_TO_FIRST_OUTPUT_BUCKET_BOUNDARIES_S = (
    0.05,
    0.1,
    0.25,
    0.5,
    0.75,
    1.0,
    1.5,
    2.0,
    3.0,
    5.0,
    10.0,
    30.0,
)

# ---------------------------------------------------------------------------
# Instrument specs
# ---------------------------------------------------------------------------

TURN_DURATION_SPEC = InstrumentSpec(
    name=semconv.METRIC_TURN_DURATION,
    kind=InstrumentKind.HISTOGRAM,
    unit="s",
    description=(
        "Seconds from engine-turn processing start to its terminal state. "
        "Recorded once per eligible engine turn; its per-outcome counts are "
        "also the turn-outcome distribution. Attributes: "
        "rasa.turn.input.type (speech, text, dtmf, or silence_timeout) and "
        "rasa.turn.outcome (completed, interrupted by new user input, "
        "cancelled by call teardown or shutdown, or error after an unhandled "
        "failure)."
    ),
    allowed_attribute_keys=frozenset(
        {
            semconv.METRIC_ATTR_TURN_INPUT_TYPE,
            semconv.METRIC_ATTR_TURN_OUTCOME,
        }
    ),
    bucket_boundaries_s=TURN_DURATION_BUCKET_BOUNDARIES_S,
)

TURN_TIME_TO_FIRST_OUTPUT_SPEC = InstrumentSpec(
    name=semconv.METRIC_TURN_TIME_TO_FIRST_OUTPUT,
    kind=InstrumentKind.HISTOGRAM,
    unit="s",
    description=(
        "Seconds from the turn trigger (speech stop, text ingress, completed "
        "DTMF collection, or a fired silence timeout) to the first output in "
        "the expected modality (first generated TTS audio chunk, streamed "
        "token, or committed agent message). Includes queueing and composition "
        "before processing. Recorded only when that output is observed. "
        "Attributes: rasa.turn.input.type and rasa.turn.output.type (audio "
        "or text)."
    ),
    allowed_attribute_keys=frozenset(
        {
            semconv.METRIC_ATTR_TURN_INPUT_TYPE,
            semconv.METRIC_ATTR_TURN_OUTPUT_TYPE,
        }
    ),
    bucket_boundaries_s=TURN_TIME_TO_FIRST_OUTPUT_BUCKET_BOUNDARIES_S,
)

TURN_INSTRUMENT_SPECS: Tuple[InstrumentSpec, ...] = (
    TURN_DURATION_SPEC,
    TURN_TIME_TO_FIRST_OUTPUT_SPEC,
)


def turn_metric_views() -> List[View]:
    """Build OpenTelemetry Views for the turn instruments.

    The ``MeterProvider`` created in ``rasa.tracing.metrics_config`` uses
    these views.
    """
    return [spec.to_view() for spec in TURN_INSTRUMENT_SPECS]


def register_turn_metric_instruments() -> None:
    """Register the turn instruments with the configured SDK provider.

    Called from ``configure_metrics()`` after the meter provider is set.
    """
    register_instruments(semconv.TURN_METER_NAME, TURN_INSTRUMENT_SPECS)
